// 自动生成，不要手改。来源：tools/build-sources.mjs（npm run sources）
window.MH_SOURCES = {"src/effects.css":"/* @css base */\n/* Motion Hub 效果样式：配色变量（黑白朱砂：浅色纸白 + 朱砂红，深色纯黑 + 亮红）+ 各效果用到的样式 + 整页过渡遮罩。按“@css 名称”标记分段，复制代码时只带用到的段。 */\n:root{\n  --paper:#FAFAF7;--paper2:#EFEFEA;--ink:#0A0A0A;--body:#2B2B2B;--dim:#7B7B78;--rule:#DCDCD6;--accent:#C8281E;--on-accent:#fff;\n  --serif:\"Songti SC\",\"STSong\",\"Noto Serif SC\",serif;\n  --sans:\"PingFang SC\",\"Helvetica Neue\",\"Noto Sans SC\",sans-serif;\n  --latin:\"Iowan Old Style\",Palatino,Georgia,serif;\n  --mono:\"SF Mono\",Menlo,monospace;\n}\n[data-theme=\"night\"]{--paper:#000000;--paper2:#0F0F0F;--ink:#FFFFFF;--body:#CFCFCF;--dim:#808080;--rule:#262626;--accent:#FF3B30;--on-accent:#fff}\n[data-theme=\"day\"]{--paper:#FAFAF7;--paper2:#EFEFEA;--ink:#0A0A0A;--body:#2B2B2B;--dim:#7B7B78;--rule:#DCDCD6;--accent:#C8281E;--on-accent:#fff}\n/* @css sm */\n/* ───── 深浅开关（和“太阳月亮开关”同一套图形） ───── */\n.sm{display:inline-grid;place-items:center;width:36px;height:36px;padding:0;border:1px solid currentColor;background:none;cursor:pointer;color:var(--ink)}\n.sm svg{width:18px;height:18px;overflow:visible}\n.sm .core{transform-origin:12px 12px;transition:transform .5s cubic-bezier(.3,.8,.2,1)}\n.sm .bite{transition:transform .5s cubic-bezier(.3,.8,.2,1)}\n.sm .rays{transform-origin:12px 12px;transition:transform .5s cubic-bezier(.3,.8,.2,1),opacity .3s}\n.sm.moon .core{transform:scale(1.5)}\n.sm.moon .bite{transform:translate(-10.5px,4.5px)}\n.sm.moon .rays{transform:rotate(-45deg) scale(.4);opacity:0}\n.sm:hover{color:var(--accent)}\n\n/* @css canvas */\n/* ───── 效果共用 ───── */\n.mh-canvas{position:absolute;inset:0;width:100%;height:100%;display:block}\n/* @css ui-center */\n.ui-center{position:absolute;inset:0;display:grid;place-items:center;align-content:center;gap:14px}\n\n/* @css tt */\n/* 深浅过渡的小页面 */\n.tt{position:absolute;inset:0;overflow:hidden;perspective:1400px;background:#0b0b0c;cursor:pointer}\n.tt-scene{position:absolute;inset:0;background:var(--paper) radial-gradient(circle,color-mix(in srgb,var(--dim) 45%,transparent) 1.1px,transparent 1.6px) 0 0/22px 22px;color:var(--ink);backface-visibility:hidden}\n.tt-mock{position:absolute;left:8%;top:50%;transform:translateY(-50%);width:60%}\n.tt-mock .tt-tag{font:500 2.2cqw/1 var(--sans);letter-spacing:.3em;color:var(--accent)}\n.tt-mock b{display:block;margin-top:1.4cqw;font:900 15cqw/1 var(--serif)}\n.tt-mock i{display:block;height:1.1cqw;margin-top:2.2cqw;background:var(--rule);width:80%}\n.tt-mock i.short{width:46%}\n.tt-scene[data-fx=\"dots\"]{\n  -webkit-mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--band)),transparent calc(var(--vr) - var(--band) + 1px)),radial-gradient(circle,#000 calc(var(--tile) * .25),transparent calc(var(--tile) * .28)),radial-gradient(circle at var(--vx) var(--vy),transparent calc(var(--vr) - var(--band) - 10px),#000 calc(var(--vr) - var(--band)),#000 var(--vr),transparent var(--vr));\n  -webkit-mask-size:100% 100%,var(--tile) var(--tile),100% 100%;-webkit-mask-composite:source-over,source-in;\n  mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--band)),transparent calc(var(--vr) - var(--band) + 1px)),radial-gradient(circle,#000 calc(var(--tile) * .25),transparent calc(var(--tile) * .28)),radial-gradient(circle at var(--vx) var(--vy),transparent calc(var(--vr) - var(--band) - 10px),#000 calc(var(--vr) - var(--band)),#000 var(--vr),transparent var(--vr));\n  mask-size:100% 100%,var(--tile) var(--tile),100% 100%;mask-composite:add,intersect}\n.tt-scene[data-fx=\"blinds\"]{-webkit-mask-image:repeating-linear-gradient(90deg,#000 0 var(--vw),transparent var(--vw) var(--period));mask-image:repeating-linear-gradient(90deg,#000 0 var(--vw),transparent var(--vw) var(--period))}\n.tt-scene[data-fx=\"halftone\"]{-webkit-mask-image:radial-gradient(circle,#000 var(--vr),transparent calc(var(--vr) + .5px));-webkit-mask-size:var(--tile) var(--tile);mask-image:radial-gradient(circle,#000 var(--vr),transparent calc(var(--vr) + .5px));mask-size:var(--tile) var(--tile)}\n.tt-scene[data-fx=\"soft\"]{-webkit-mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--soft)),transparent var(--vr));mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--soft)),transparent var(--vr))}\n\n/* @css vfx */\n/* 整页深浅切换（MH.themeSwitch，View Transitions） */\n[data-vfx]:not([data-vfx=\"fade\"])::view-transition-old(root),[data-vfx]:not([data-vfx=\"fade\"])::view-transition-new(root){animation:none;mix-blend-mode:normal}\n[data-vfx=\"dots\"]::view-transition-new(root){\n  -webkit-mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--band)),transparent calc(var(--vr) - var(--band) + 1px)),radial-gradient(circle,#000 calc(var(--tile) * .25),transparent calc(var(--tile) * .28)),radial-gradient(circle at var(--vx) var(--vy),transparent calc(var(--vr) - var(--band) - 10px),#000 calc(var(--vr) - var(--band)),#000 var(--vr),transparent var(--vr));\n  -webkit-mask-size:100% 100%,var(--tile) var(--tile),100% 100%;-webkit-mask-composite:source-over,source-in;\n  mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--band)),transparent calc(var(--vr) - var(--band) + 1px)),radial-gradient(circle,#000 calc(var(--tile) * .25),transparent calc(var(--tile) * .28)),radial-gradient(circle at var(--vx) var(--vy),transparent calc(var(--vr) - var(--band) - 10px),#000 calc(var(--vr) - var(--band)),#000 var(--vr),transparent var(--vr));\n  mask-size:100% 100%,var(--tile) var(--tile),100% 100%;mask-composite:add,intersect}\n[data-vfx=\"blinds\"]::view-transition-new(root){-webkit-mask-image:repeating-linear-gradient(90deg,#000 0 var(--vw),transparent var(--vw) var(--period));mask-image:repeating-linear-gradient(90deg,#000 0 var(--vw),transparent var(--vw) var(--period))}\n[data-vfx=\"halftone\"]::view-transition-new(root){-webkit-mask-image:radial-gradient(circle,#000 var(--vr),transparent calc(var(--vr) + .5px));-webkit-mask-size:var(--tile) var(--tile);mask-image:radial-gradient(circle,#000 var(--vr),transparent calc(var(--vr) + .5px));mask-size:var(--tile) var(--tile)}\n[data-vfx=\"soft\"]::view-transition-new(root){-webkit-mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--soft)),transparent var(--vr));mask-image:radial-gradient(circle at var(--vx) var(--vy),#000 calc(var(--vr) - var(--soft)),transparent var(--vr))}\n[data-vfx=\"flip\"]::view-transition-group(root){background:#0b0b0c}\n[data-vfx=\"flip\"]::view-transition-old(root),[data-vfx=\"flip\"]::view-transition-new(root){backface-visibility:hidden}\n\n/* @css pd */\n/* 拉扯翻页 */\n.pd{position:absolute;inset:0;overflow:hidden;user-select:none;-webkit-user-select:none;cursor:grab}\n.pd:active{cursor:grabbing}\n.pd-slide{position:absolute;inset:0;display:none;align-items:center;gap:6cqw;padding:0 8cqw}\n.pd-slide.on{display:flex}\n.pd-n{font:italic 400 30cqh/.8 var(--latin);color:transparent;-webkit-text-stroke:1.5px var(--ink)}\n.pd-slide h3{font:900 9cqh/1.1 var(--serif)}\n.pd-slide p{margin-top:2cqh;font:400 3.4cqh/1.6 var(--serif);color:var(--body)}\n.pd-pn{position:absolute;right:20px;bottom:16px;font:500 12px/1 var(--mono);color:var(--dim)}\n.pd-sheet{position:absolute;inset:0;pointer-events:none;z-index:5}\n.pd-band{position:absolute;left:0;width:100%;overflow:hidden;transform-origin:0 0;will-change:transform}\n.pd-band>.pd-slide{display:flex}\n\n/* @css sm-stage */\n/* 太阳月亮开关（舞台版，大号） */\n.ui-center .sm{width:22cqh;height:22cqh;border-width:2px}\n.ui-center .sm svg{width:11cqh;height:11cqh}\n.sm-tip{font:500 12px/1 var(--mono);letter-spacing:.2em;color:var(--dim)}\n\n/* @css gc */\n/* 边框高光卡片 */\n.gc-wrap{position:absolute;inset:0;display:grid;grid-template-columns:repeat(3,1fr);gap:3cqw;align-items:center;padding:0 7cqw;perspective:900px}\n.gc{position:relative;aspect-ratio:3/4;padding:3cqw;border:1px solid var(--rule);background:var(--paper);display:flex;flex-direction:column;transition:transform .5s cubic-bezier(.3,.8,.2,1)}\n.gc::before{content:\"\";position:absolute;inset:-1px;padding:1.5px;background:radial-gradient(260px circle at var(--mx,50%) var(--my,50%),var(--accent),transparent 70%);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;opacity:0;transition:opacity .3s}\n.gc.hot::before{opacity:1}\n.gc span{font:italic 400 2.4cqw/1 var(--latin);color:var(--accent)}\n.gc b{margin-top:auto;font:900 3.2cqw/1.2 var(--serif)}\n.gc em{margin-top:1cqw;font:500 1.6cqw/1 var(--sans);font-style:normal;color:var(--dim)}\n\n/* @css sc */\n/* 乱码落定 */\n.sc{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;gap:2.4cqh;padding:0 8cqw}\n.sc-w{font:600 8cqh/1.1 var(--mono);letter-spacing:.04em;color:var(--dim);transition:color .2s;white-space:nowrap}\n.sc-w.hot{color:var(--accent)}\n\n/* @css ft */\n/* 跟随信息卡 */\n.ft{position:absolute;inset:0;padding:8cqh 8cqw;display:flex;flex-direction:column;justify-content:center}\n.ft-row{display:flex;gap:3cqw;align-items:baseline;padding:2.4cqh 0;border-top:1px solid var(--rule)}\n.ft-row:last-of-type{border-bottom:1px solid var(--rule)}\n.ft-row span{font:500 1.6cqw/1 var(--mono);color:var(--dim)}\n.ft-row b{font:700 6cqh/1.1 var(--serif);transition:transform .4s cubic-bezier(.3,.8,.2,1),color .2s}\n.ft-row.hot b{transform:translateX(1.4cqw);color:var(--accent)}\n.ft-tip{position:absolute;left:0;top:0;width:max(180px,24cqw);padding:12px 14px;border:1px solid var(--ink);background:var(--paper);pointer-events:none;opacity:0;transform:scale(.92);transition:opacity .2s,transform .25s cubic-bezier(.3,.8,.2,1)}\n.ft-tip.on{opacity:1;transform:scale(1)}\n.ft-tip em{display:block;font:500 11px/1 var(--mono);font-style:normal;letter-spacing:.1em;color:var(--accent)}\n.ft-tip i{display:block;margin-top:8px;font:500 12px/1.5 var(--mono);font-style:normal;color:var(--body)}\n\n/* @css pl */\n/* 校验链 */\n.pl{position:absolute;left:8cqw;right:8cqw;top:50%;transform:translateY(-50%)}\n.pl svg{display:block;width:100%;height:90px;overflow:visible}\n.pl .ln{stroke:var(--rule);stroke-width:2}\n.pl .lnon{stroke:var(--accent);stroke-width:2}\n.pl .g{fill:var(--paper);stroke:var(--dim);stroke-width:1.5;transition:fill .25s,stroke .25s}\n.pl .g.on{fill:var(--accent);stroke:var(--accent)}\n.pl text{font:500 13px var(--sans);fill:var(--dim);text-anchor:middle;transition:fill .25s}\n.pl text.on{fill:var(--ink)}\n.pl .tok{fill:var(--ink)}\n","src/core.js":"// Motion Hub 核心：注册表 + 公共工具。所有效果文件都是普通 <script>（不是 ES 模块），\n// 这样直接双击 index.html（file://）也能运行。每个效果调用 MH.register({...}) 把自己登记进来。\n//\n// 效果对象的约定：\n//   id      唯一标识（小写短横线）\n//   name    中文名\n//   cat     分类：背景 / 过渡 / 翻页 / 片头 / 交互\n//   tech    用到的技术（展示用）\n//   desc    一句话说明\n//   mount(el, opts) → { pause(), resume(), destroy() }\n//     el 是一个已经有尺寸的容器；opts.expanded 为 true 表示全屏体验（关掉幽灵光标、允许滚轮等）\nwindow.MH = (() => {\n  const effects = [];\n  // 记下效果来自哪个文件（复制代码时只带这个文件）\n  const register = e => { const src = document.currentScript && document.currentScript.src; e.file = e.file || (src ? src.split('/').pop() : ''); effects.push(e); };\n  const still = () => matchMedia('(prefers-reduced-motion: reduce)').matches;\n  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));\n  const lerp = (a, b, k) => a + (b - a) * k;\n  const ease = {\n    in: t => t * t * t,\n    out: t => 1 - (1 - t) ** 3,\n    inOut: t => t < .5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2,\n    back: t => { const c = 1.4; return 1 + (c + 1) * (t - 1) ** 3 + c * (t - 1) ** 2; },\n  };\n  const hash = i => { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };\n\n  // 二维 Perlin 噪声，seed 决定排列表\n  function perlin(seed = 1) {\n    const P = new Uint8Array(512), p = [...Array(256).keys()];\n    let s = seed;\n    for (let i = 255; i > 0; i--) { s = (s * 16807) % 2147483647; const j = s % (i + 1); [p[i], p[j]] = [p[j], p[i]]; }\n    for (let i = 0; i < 512; i++) P[i] = p[i & 255];\n    const fade = t => t * t * t * (t * (t * 6 - 15) + 10), grad = (h, x, y) => ((h & 1) ? -x : x) + ((h & 2) ? -y : y);\n    return (x, y) => {\n      const X = Math.floor(x) & 255, Y = Math.floor(y) & 255; x -= Math.floor(x); y -= Math.floor(y);\n      const u = fade(x), v = fade(y), a = P[X] + Y, b = P[X + 1] + Y;\n      const l1 = grad(P[a], x, y) + u * (grad(P[b], x - 1, y) - grad(P[a], x, y));\n      const l2 = grad(P[a + 1], x, y - 1) + u * (grad(P[b + 1], x - 1, y - 1) - grad(P[a + 1], x, y - 1));\n      return l1 + v * (l2 - l1);\n    };\n  }\n\n  // 画布按设备像素比放大，画的时候仍用 CSS 像素坐标\n  function fit(cv, w, h) {\n    const dpr = Math.min(devicePixelRatio || 1, 2);\n    cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);\n    const ctx = cv.getContext('2d'); ctx.setTransform(dpr, 0, 0, dpr, 0, 0); return ctx;\n  }\n  // 从容器读主题色（--paper / --ink / --dim / --rule / --accent）\n  function colors(el) {\n    const cs = getComputedStyle(el), v = n => cs.getPropertyValue(n).trim();\n    const t = el.closest('[data-theme]');\n    return { paper: v('--paper'), ink: v('--ink'), dim: v('--dim'), rule: v('--rule'), accent: v('--accent'), night: !!t && t.dataset.theme === 'night' };\n  }\n  // 一段时长 ms 的补间，fn(k) 中 k 从 0 到 1；减少动态效果时直接到终点\n  const tween = (ms, fn) => new Promise(res => {\n    if (still()) { fn(1); return res(); }\n    const t0 = performance.now();\n    const f = now => { const k = clamp((now - t0) / ms); fn(k); k < 1 ? requestAnimationFrame(f) : res(); };\n    requestAnimationFrame(f);\n  });\n  // 尺寸缩放系数：全屏约 1，缩略图约 0.45，让小画面像“整页缩小”而不是挤满细节\n  const scaleOf = W => clamp(W / 1200, .45, 1);\n\n  // 幽灵光标：没人操作时，沿一条利萨如曲线在容器里慢慢移动，让缩略图自己演示交互\n  const ghostAt = (now, W, H, seed = 0) => {\n    const t = now / 1000 + seed * 7;\n    return { x: W * (.5 + .32 * Math.sin(t * .55) * Math.cos(t * .21)), y: H * (.5 + .3 * Math.sin(t * .83 + 1.3)) };\n  };\n\n  // 效果宿主：（可选）建画布、跟随尺寸、换算局部指针坐标、管动画循环和暂停。\n  // setup(h) 返回 { resize(W,H), frame(now), down(x,y), theme(), ghostClick }，h 提供 ctx / W / H / P / s / colors()\n  // ghostClick: false 表示幽灵光标不替它“点击”（例如片头，点一下会重播）\n  function canvasHost(el, opts, setup, { canvas = true } = {}) {\n    const cv = canvas ? document.createElement('canvas') : null;\n    if (cv) { cv.className = 'mh-canvas'; el.append(cv); }\n    let ctx, W = 0, H = 0, raf = 0, running = false, lastReal = -1e9, lastGhostClick = 0;\n    const P = { x: -9999, y: -9999, real: false };\n    const seed = hash(effects.length + el.childElementCount);\n    const h = { cv, get ctx() { return ctx; }, get W() { return W; }, get H() { return H; }, P, s: 1, colors: () => colors(el), expanded: !!opts.expanded };\n    const api = setup(h);\n    const size = () => {\n      const r = el.getBoundingClientRect(); if (!r.width || !r.height) return;\n      W = r.width; H = r.height; h.s = scaleOf(W); if (cv) ctx = fit(cv, W, H); api.resize && api.resize(W, H);\n      if (!running) api.frame(performance.now());\n    };\n    const ro = new ResizeObserver(size); ro.observe(el);\n    const local = e => { const r = el.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; };\n    const onMove = e => { [P.x, P.y] = local(e); P.real = true; lastReal = performance.now(); };\n    const onLeave = () => { P.real = false; P.x = P.y = -9999; };\n    const onDown = e => { if (e.target.closest('a, button')) return; lastReal = performance.now(); const [x, y] = local(e); api.down && api.down(x, y); };\n    el.addEventListener('pointermove', onMove); el.addEventListener('pointerleave', onLeave); el.addEventListener('pointerdown', onDown);\n    const mo = new MutationObserver(() => { api.theme && api.theme(); if (!running) api.frame(performance.now()); });\n    mo.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme', 'data-palette'] });\n    const tick = now => {\n      if (!running) return;\n      // 缩略图里 2.5 秒没人碰，就让幽灵光标接管；偶尔“点”一下展示点击效果\n      if (!h.expanded && now - lastReal > 2500) {\n        const g = ghostAt(now, W, H, seed); P.x = g.x; P.y = g.y;\n        if (api.down && api.ghostClick !== false && now - lastGhostClick > 4200) { lastGhostClick = now; api.down(g.x, g.y); }\n      }\n      if (W && H) api.frame(now);\n      raf = requestAnimationFrame(tick);\n    };\n    size();\n    return {\n      pause() { running = false; cancelAnimationFrame(raf); },\n      resume() { if (running) return; if (still()) { api.frame(performance.now()); return; } running = true; raf = requestAnimationFrame(tick); },\n      destroy() { this.pause(); ro.disconnect(); mo.disconnect(); el.removeEventListener('pointermove', onMove); el.removeEventListener('pointerleave', onLeave); el.removeEventListener('pointerdown', onDown); cv && cv.remove(); },\n    };\n  }\n\n  // 让 CSS 能对自定义属性做补间（遮罩半径等）\n  if (window.CSS && CSS.registerProperty) {\n    for (const name of ['--vr', '--vw']) { try { CSS.registerProperty({ name, syntax: '<length>', inherits: false, initialValue: '0px' }); } catch (e) { /* 已注册 */ } }\n  }\n\n  return { effects, register, still, clamp, lerp, ease, hash, perlin, fit, colors, tween, scaleOf, ghostAt, canvasHost };\n})();\n","src/effects/contour.js":"// 背景动效：画在 canvas 上，尺寸跟随容器，h.s 是缩放系数（全屏约 1，缩略图约 0.45）。\n\n// ───── 等高线：平滑噪声当地形，每隔一个高度描一圈线（marching squares）；鼠标处隆起，点击泛起波纹 ─────\nMH.register({\n  id: 'contour', name: '等高线', cat: '背景', tech: 'Canvas · Perlin 噪声 · Marching Squares',\n  desc: '地形缓慢漂移，鼠标处隆起一座小山，最高的几圈变成强调色；点击会荡开一圈圈波纹。',\n  mount: (el, opts) => MH.canvasHost(el, opts, h => {\n    const noise = MH.perlin(3), LEVELS = [], m = { x: -999, y: -999, a: 0 }, waves = [];\n    for (let l = -1.2; l <= 1.65; l += .12) LEVELS.push(l);\n    let C = h.colors(), CELL, cols, rows, field;\n    return {\n      resize(W, H) { CELL = Math.max(6, 14 * h.s); cols = Math.ceil(W / CELL) + 1; rows = Math.ceil(H / CELL) + 1; field = new Float32Array(cols * rows); },\n      theme() { C = h.colors(); },\n      down(x, y) { waves.push({ x, y, t0: performance.now() }); if (waves.length > 4) waves.shift(); },\n      frame(now) {\n        const { ctx, W, H, P, s } = h, t = now / 1000 * .02, SC = 1 / (420 * s);\n        const on = P.x > -999;\n        if (on && m.x < -900) { m.x = P.x; m.y = P.y; }\n        m.x += ((on ? P.x : m.x) - m.x) * .12; m.y += ((on ? P.y : m.y) - m.y) * .12; m.a += ((on ? 1 : 0) - m.a) * .06;\n        const R2 = 33800 * s * s, live = waves.filter(w => now - w.t0 < 2600);\n        for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {\n          const px = i * CELL, py = j * CELL, wx = px * SC, wy = py * SC;\n          let v = noise(wx + t, wy) * 1.1 + noise(wx * 2.1 - t * .7, wy * 2.1 + 9) * .45;\n          if (m.a > .01) { const dx = px - m.x, dy = py - m.y; v += .9 * m.a * Math.exp(-(dx * dx + dy * dy) / R2); }\n          for (const w of live) {\n            const age = (now - w.t0) / 1000, d = Math.hypot(px - w.x, py - w.y), front = age * 420 * s;\n            if (Math.abs(d - front) < 160 * s) v += .35 * Math.cos((d - front) / (26 * s)) * Math.exp(-(((d - front) / (90 * s)) ** 2)) * (1 - age / 2.6);\n          }\n          field[j * cols + i] = v;\n        }\n        ctx.clearRect(0, 0, W, H); ctx.lineWidth = 1;\n        for (let li = 0; li < LEVELS.length; li++) {\n          const L = LEVELS[li], hot = L >= 1;\n          ctx.strokeStyle = hot ? C.accent : C.dim;\n          ctx.globalAlpha = hot ? .6 : (li % 5 === 0 ? (C.night ? .32 : .42) : (C.night ? .16 : .22));\n          ctx.beginPath();\n          for (let j = 0; j < rows - 1; j++) for (let i = 0; i < cols - 1; i++) {\n            const a = field[j * cols + i], b = field[j * cols + i + 1], c = field[(j + 1) * cols + i + 1], d = field[(j + 1) * cols + i];\n            const k = (a > L) | ((b > L) << 1) | ((c > L) << 2) | ((d > L) << 3);\n            if (k === 0 || k === 15) continue;\n            const x0 = i * CELL, y0 = j * CELL, R = x0 + CELL, B = y0 + CELL;\n            const Tx = x0 + (L - a) / (b - a) * CELL, Ry = y0 + (L - b) / (c - b) * CELL, Bx = x0 + (L - d) / (c - d) * CELL, Ly = y0 + (L - a) / (d - a) * CELL;\n            switch (k) {\n              case 1: case 14: ctx.moveTo(x0, Ly); ctx.lineTo(Tx, y0); break;\n              case 2: case 13: ctx.moveTo(Tx, y0); ctx.lineTo(R, Ry); break;\n              case 3: case 12: ctx.moveTo(x0, Ly); ctx.lineTo(R, Ry); break;\n              case 4: case 11: ctx.moveTo(R, Ry); ctx.lineTo(Bx, B); break;\n              case 6: case 9: ctx.moveTo(Tx, y0); ctx.lineTo(Bx, B); break;\n              case 7: case 8: ctx.moveTo(x0, Ly); ctx.lineTo(Bx, B); break;\n              case 5: ctx.moveTo(x0, Ly); ctx.lineTo(Tx, y0); ctx.moveTo(R, Ry); ctx.lineTo(Bx, B); break;\n              case 10: ctx.moveTo(Tx, y0); ctx.lineTo(R, Ry); ctx.moveTo(x0, Ly); ctx.lineTo(Bx, B); break;\n            }\n          }\n          ctx.stroke();\n        }\n        ctx.globalAlpha = 1;\n      },\n    };\n  }),\n});\n","src/effects/dots.js":"// 背景动效：画在 canvas 上，尺寸跟随容器，h.s 是缩放系数（全屏约 1，缩略图约 0.45）。\n\n// ───── 磁性点阵：每个点有静止位置，被鼠标推开、被弹簧拉回；推得越远越大、越接近强调色；点击发出冲击波 ─────\nfunction dotField(quiet) {\n  return (el, opts) => MH.canvasHost(el, opts, h => {\n    let C = h.colors(), dots = [], GAP, R;\n    const waves = [];\n    return {\n      resize(W, H) {\n        GAP = Math.max(10, 26 * h.s); R = (quiet ? 110 : 150) * h.s; dots = [];\n        const ox = (W % GAP) / 2, oy = (H % GAP) / 2;\n        for (let y = oy; y < H; y += GAP) for (let x = ox; x < W; x += GAP) dots.push({ hx: x, hy: y, x, y, vx: 0, vy: 0 });\n      },\n      theme() { C = h.colors(); },\n      down: quiet ? null : (x, y) => { waves.push({ x, y, t0: performance.now() }); if (waves.length > 3) waves.shift(); },\n      frame(now) {\n        const { ctx, W, H, P, s } = h, t = now / 1000, live = waves.filter(w => now - w.t0 < 1800);\n        const push = quiet ? 1.6 : 3.2, base = new Path2D(), hot = new Path2D();\n        for (const d of dots) {\n          const dx = d.x - P.x, dy = d.y - P.y, dist = Math.hypot(dx, dy);\n          if (dist < R && dist > .1) { const f = (1 - dist / R) ** 2 * push * s; d.vx += dx / dist * f; d.vy += dy / dist * f; }\n          for (const w of live) {\n            const age = (now - w.t0) / 1000, wx = d.hx - w.x, wy = d.hy - w.y, wd = Math.hypot(wx, wy), front = age * 700 * s;\n            const g = Math.exp(-(((wd - front) / (40 * s)) ** 2)) * (1 - age / 1.8) * 1.3 * s;\n            if (g > .01 && wd > 1) { d.vx += wx / wd * g; d.vy += wy / wd * g; }\n          }\n          d.vx += (d.hx - d.x) * .06; d.vy += (d.hy - d.y) * .06; d.vx *= .82; d.vy *= .82; d.x += d.vx; d.y += d.vy;\n          const off = Math.hypot(d.x - d.hx, d.y - d.hy) / s;\n          const breathe = quiet ? 0 : Math.sin(d.hx * .012 / s + d.hy * .008 / s - t * 1.2) * .25;\n          const r = Math.min(1.1 + breathe + off * (quiet ? .06 : .09), quiet ? 2.4 : 3.6) * Math.max(.7, s);\n          const p = off > (quiet ? 6 : 7) ? hot : base;\n          p.moveTo(d.x + r, d.y); p.arc(d.x, d.y, r, 0, Math.PI * 2);\n        }\n        ctx.clearRect(0, 0, W, H);\n        ctx.fillStyle = C.dim; ctx.globalAlpha = quiet ? (C.night ? .26 : .3) : (C.night ? .38 : .42); ctx.fill(base);\n        ctx.fillStyle = C.accent; ctx.globalAlpha = quiet ? .6 : .85; ctx.fill(hot); ctx.globalAlpha = 1;\n      },\n    };\n  });\n}\nMH.register({ id: 'dots', name: '磁性点阵', cat: '背景', tech: 'Canvas · 弹簧阻尼', desc: '整屏点阵被鼠标推开再弹回，推开的点变大、变成强调色；点击发出一圈冲击波。', mount: dotField(false) });\nMH.register({ id: 'dots-quiet', name: '安静点阵', cat: '背景', tech: 'Canvas · 弹簧阻尼', desc: '同一套点阵的阅读版：点更淡、推开的范围和力度更小，没有冲击波，适合长文页面。', mount: dotField(true) });\n","src/effects/flow.js":"// 背景动效：画在 canvas 上，尺寸跟随容器，h.s 是缩放系数（全屏约 1，缩略图约 0.45）。\n\n// ───── 风场：粒子顺着噪声角度流动，画布每帧轻微擦掉一点形成拖尾；鼠标附近卷成漩涡 ─────\nMH.register({\n  id: 'flow', name: '风场', cat: '背景', tech: 'Canvas · 粒子 · 噪声流场',\n  desc: '几千个粒子顺着看不见的风流动，留下淡淡的拖尾；鼠标附近被卷成漩涡，经过的粒子变成强调色。',\n  mount: (el, opts) => MH.canvasHost(el, opts, h => {\n    const noise = MH.perlin(11);\n    let C = h.colors(), ps = [];\n    const spawn = p => { p.x = Math.random() * h.W; p.y = Math.random() * h.H; p.life = 80 + Math.random() * 160; p.hot = 0; return p; };\n    return {\n      resize(W, H) { ps = Array.from({ length: Math.round(W * H / (1100 * h.s * h.s)) }, () => spawn({})); },\n      theme() { C = h.colors(); h.ctx && h.ctx.clearRect(0, 0, h.W, h.H); },\n      frame(now) {\n        const { ctx, W, H, P, s } = h, t = now / 1000, SC = 380 * s, R2 = 32000 * s * s;\n        ctx.globalCompositeOperation = 'destination-out'; ctx.fillStyle = 'rgba(0,0,0,.07)'; ctx.fillRect(0, 0, W, H);\n        ctx.globalCompositeOperation = 'source-over';\n        const cold = new Path2D(), warm = new Path2D();\n        for (const p of ps) {\n          const a = noise(p.x / SC + t * .03, p.y / SC) * Math.PI * 2.4;\n          let vx = Math.cos(a) * 1.1 * s, vy = Math.sin(a) * 1.1 * s;\n          const dx = p.x - P.x, dy = p.y - P.y, d2 = dx * dx + dy * dy;\n          if (d2 < R2) { const d = Math.sqrt(d2) + 1, f = (1 - d2 / R2) * 5 * s; vx += -dy / d * f + dx / d * f * .25; vy += dx / d * f + dy / d * f * .25; p.hot = 1; }\n          p.hot *= .97;\n          const path = p.hot > .25 ? warm : cold;\n          path.moveTo(p.x, p.y); p.x += vx; p.y += vy; path.lineTo(p.x, p.y);\n          if (--p.life < 0 || p.x < -10 || p.x > W + 10 || p.y < -10 || p.y > H + 10) spawn(p);\n        }\n        ctx.lineWidth = 1;\n        ctx.strokeStyle = C.dim; ctx.globalAlpha = C.night ? .45 : .5; ctx.stroke(cold);\n        ctx.strokeStyle = C.accent; ctx.globalAlpha = .9; ctx.stroke(warm); ctx.globalAlpha = 1;\n      },\n    };\n  }),\n});\n","src/effects/follow-tip.js":"// 小交互：DOM + CSS，没有画布。用 canvasHost 的无画布模式拿到“真实指针或幽灵光标”的位置。\n\n// ───── 跟随光标的信息卡：悬停列表行时，一张小卡片带一点延迟地跟着指针；靠近右边缘时翻到指针左侧 ─────\nMH.register({\n  id: 'follow-tip', name: '跟随信息卡', cat: '交互', tech: '线性插值 · 指针跟随',\n  desc: '悬停在某一行时，信息卡带着一点“拖拽感”跟随指针，靠近边缘会自动翻到另一侧。',\n  mount(el, opts) {\n    const ROWS = [['01', '等高线', 'Canvas · Marching Squares'], ['02', '磁性点阵', 'Canvas · 弹簧阻尼'], ['03', '风场', 'Canvas · 粒子'], ['04', '拉扯翻页', 'DOM 切条']];\n    el.insertAdjacentHTML('beforeend', `<div class=\"ft\">${ROWS.map(([n, t]) => `<div class=\"ft-row\"><span>${n}</span><b>${t}</b></div>`).join('')}<div class=\"ft-tip\"><em></em><i></i></div></div>`);\n    const box = el.lastElementChild, rows = [...box.querySelectorAll('.ft-row')], tip = box.querySelector('.ft-tip');\n    const p = { x: 0, y: 0 };\n    return MH.canvasHost(el, opts, h => ({\n      frame() {\n        const r0 = el.getBoundingClientRect(), W = h.W;\n        const i = rows.findIndex(r => { const b = r.getBoundingClientRect(), y = h.P.y + r0.top, x = h.P.x + r0.left; return y >= b.top && y <= b.bottom && x >= b.left && x <= b.right; });\n        tip.classList.toggle('on', i >= 0);\n        rows.forEach((r, k) => r.classList.toggle('hot', k === i));\n        if (i >= 0) { tip.querySelector('em').textContent = `${ROWS[i][0]} / 0${ROWS.length}`; tip.querySelector('i').textContent = ROWS[i][2]; }\n        const tw = tip.offsetWidth, tx = h.P.x + (h.P.x > W - tw - 30 ? -tw - 14 : 18), ty = h.P.y + 16;\n        const k = MH.still() ? 1 : .18; p.x += (tx - p.x) * k; p.y += (ty - p.y) * k;\n        tip.style.translate = `${p.x}px ${p.y}px`;\n      },\n    }), { canvas: false });\n  },\n});\n","src/effects/glow-card.js":"// 小交互：DOM + CSS，没有画布。用 canvasHost 的无画布模式拿到“真实指针或幽灵光标”的位置。\n\n// ───── 边框高光卡片：只在边框那 1.5px 上画一个跟着指针的径向渐变（不给文字铺底色），外加轻微 3D 倾斜 ─────\nMH.register({\n  id: 'glow-card', name: '边框高光卡片', cat: '交互', tech: 'CSS 遮罩 · mask-composite · 3D 倾斜',\n  desc: '指针在卡片上移动时，边框沿着指针亮起一段光，卡片同时朝指针方向轻轻倾斜。',\n  mount(el, opts) {\n    el.insertAdjacentHTML('beforeend', `<div class=\"gc-wrap\">${['01', '02', '03'].map((n, i) => `<div class=\"gc\"><span>${n}</span><b>${['等高线', '点阵扩散', '拉扯翻页'][i]}</b><em>${['背景', '过渡', '翻页'][i]}</em></div>`).join('')}</div>`);\n    const wrap = el.lastElementChild, cards = [...wrap.children];\n    return MH.canvasHost(el, opts, h => ({\n      frame() {\n        const r0 = el.getBoundingClientRect();\n        for (const c of cards) {\n          const r = c.getBoundingClientRect(), x = h.P.x + r0.left - r.left, y = h.P.y + r0.top - r.top;\n          const inside = x >= 0 && y >= 0 && x <= r.width && y <= r.height;\n          c.classList.toggle('hot', inside);\n          if (inside) {\n            c.style.setProperty('--mx', x + 'px'); c.style.setProperty('--my', y + 'px');\n            if (!MH.still()) c.style.transform = `rotateX(${(.5 - y / r.height) * 8}deg) rotateY(${(x / r.width - .5) * 10}deg)`;\n          } else c.style.transform = '';\n        }\n      },\n    }), { canvas: false });\n  },\n});\n","src/effects/grid.js":"// 背景动效：画在 canvas 上，尺寸跟随容器，h.s 是缩放系数（全屏约 1，缩略图约 0.45）。\n\n// ───── 坐标网格：坐标纸 + 十字准线 + 坐标读数；鼠标经过的格子“加热”，四角亮起角标后慢慢冷却 ─────\nMH.register({\n  id: 'grid', name: '坐标网格', cat: '背景', tech: 'Canvas · 热度衰减',\n  desc: '坐标纸背景，鼠标拖出十字准线和实时坐标；经过的格子四角亮起红色角标，再慢慢暗下去。',\n  mount: (el, opts) => MH.canvasHost(el, opts, h => {\n    let C = h.colors(), S, cols, rows, heat;\n    const m = { px: -999, py: -999 };\n    return {\n      resize(W, H) { S = Math.max(16, 40 * h.s); cols = Math.ceil(W / S) + 1; rows = Math.ceil(H / S) + 1; heat = new Float32Array(cols * rows); },\n      theme() { C = h.colors(); },\n      frame() {\n        const { ctx, W, H, P, s } = h, on = P.x > -999;\n        ctx.clearRect(0, 0, W, H); ctx.strokeStyle = C.dim; ctx.lineWidth = 1;\n        for (let pass = 0; pass < 2; pass++) {\n          ctx.globalAlpha = pass ? (C.night ? .22 : .26) : (C.night ? .07 : .09); ctx.beginPath();\n          for (let i = 0; i < cols; i++) if ((i % 4 === 0) === !!pass) { ctx.moveTo(i * S + .5, 0); ctx.lineTo(i * S + .5, H); }\n          for (let j = 0; j < rows; j++) if ((j % 4 === 0) === !!pass) { ctx.moveTo(0, j * S + .5); ctx.lineTo(W, j * S + .5); }\n          ctx.stroke();\n        }\n        if (on && m.px > -999) { // 沿移动路径加热，快速划过也不跳格\n          const steps = Math.max(1, Math.ceil(Math.hypot(P.x - m.px, P.y - m.py) / (S / 2)));\n          for (let k = 0; k <= steps; k++) {\n            const i = Math.floor((m.px + (P.x - m.px) * k / steps) / S), j = Math.floor((m.py + (P.y - m.py) * k / steps) / S);\n            if (i >= 0 && i < cols && j >= 0 && j < rows) heat[j * cols + i] = 1;\n          }\n        }\n        m.px = on ? P.x : -999; m.py = on ? P.y : -999;\n        ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;\n        for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {\n          const v = heat[j * cols + i]; if (v < .02) continue;\n          heat[j * cols + i] = v * .955;\n          const x = i * S, y = j * S, L = (6 + v * 4) * s;\n          ctx.globalAlpha = v * .9; ctx.beginPath();\n          ctx.moveTo(x, y + L); ctx.lineTo(x, y); ctx.lineTo(x + L, y);\n          ctx.moveTo(x + S - L, y); ctx.lineTo(x + S, y); ctx.lineTo(x + S, y + L);\n          ctx.moveTo(x + S, y + S - L); ctx.lineTo(x + S, y + S); ctx.lineTo(x + S - L, y + S);\n          ctx.moveTo(x + L, y + S); ctx.lineTo(x, y + S); ctx.lineTo(x, y + S - L);\n          ctx.stroke();\n        }\n        if (on) {\n          ctx.globalAlpha = C.night ? .45 : .5; ctx.lineWidth = 1; ctx.beginPath();\n          ctx.moveTo(0, Math.round(P.y) + .5); ctx.lineTo(W, Math.round(P.y) + .5);\n          ctx.moveTo(Math.round(P.x) + .5, 0); ctx.lineTo(Math.round(P.x) + .5, H); ctx.stroke();\n          ctx.globalAlpha = .9; ctx.fillStyle = C.accent; ctx.font = `500 ${Math.max(9, 11 * s)}px \"SF Mono\",Menlo,monospace`;\n          ctx.fillText(`${Math.round(P.x)}, ${Math.round(P.y)}`, P.x + 10, P.y - 10);\n        }\n        ctx.globalAlpha = 1;\n      },\n    };\n  }),\n});\n","src/effects/intro.js":"// 点阵拼字片头：画面是时间 t 的纯函数 frame(t)，同一个 t 永远画出同一帧，所以能随时跳到结尾、重播、在任意尺寸重画最后一帧。\n//   0.0–1.3s  网格点从文字中心一圈圈亮起\n//   1.2–3.4s  屏幕外的点沿弧线飞进来，在网格缝隙里拼出文字；字形里的网格点同时变成强调色\n//   3.4–6.0s  字幕依次闪过，每出现一个，从文字中心荡开一圈波纹\n//   6.0–6.8s  收住，最后一帧可以直接当背景“定格”\nMH.register({\n  id: 'intro', name: '点阵拼字片头', cat: '片头', tech: 'Canvas · 纯函数时间轴 · 文字采样',\n  desc: '网格点亮起，屏幕外的点飞进来拼成文字，字幕依次闪过并荡开波纹；播完定格。点一下重播。',\n  usage: `MH.effects.find(e => e.id === 'intro').mount(el, { text: 'LJY', captions: ['…'] }).resume();`,\n  mount(el, opts) {\n    const TEXT = opts.text || 'LJY', CAPS = opts.captions || ['背景', '过渡', '翻页', '交互'];\n    const T_END = 6.8, HOLD = 2.6, { clamp, hash } = MH;\n    const ease = t => t < .5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;\n    const PULSES = [1.0, 3.4, 4.05, 4.7, 5.35], CAP_AT = k => 3.4 + k * .65;\n    let L = null, C, t0 = performance.now();\n    const layout = (W, H, s) => {\n      const GAP = Math.max(8, 22 * s), cx = W / 2, cy = H * .44, fs = Math.min(H * .42, W * .3);\n      const off = document.createElement('canvas'); off.width = Math.ceil(W); off.height = Math.ceil(H);\n      const c = off.getContext('2d');\n      c.font = `700 ${fs}px \"Iowan Old Style\", Palatino, Georgia, serif`;\n      if ('letterSpacing' in c) c.letterSpacing = `${fs * .06}px`;\n      c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillText(TEXT, cx, cy);\n      c.lineWidth = fs * .05; c.lineJoin = 'round'; c.strokeText(TEXT, cx, cy); // 加粗细笔画，点阵字才压得住\n      const mask = c.getImageData(0, 0, off.width, off.height).data;\n      const inside = (x, y) => { x = Math.round(x); y = Math.round(y); return x >= 0 && y >= 0 && x < off.width && y < off.height && mask[(y * off.width + x) * 4 + 3] > 120; };\n      const ox = (W % GAP) / 2, oy = (H % GAP) / 2, diag = Math.hypot(W, H), grid = [], fly = [];\n      let k = 0;\n      for (let y = oy; y < H; y += GAP) for (let x = ox; x < W; x += GAP) {\n        grid.push({ x, y, d: Math.hypot(x - cx, y - cy), letter: inside(x, y), h: hash(k++) });\n        if (inside(x + GAP / 2, y + GAP / 2)) {\n          const i = fly.length, a = hash(i * 3 + 1) * Math.PI * 2, R0 = diag * (.6 + .3 * hash(i * 3 + 2));\n          fly.push({ tx: x + GAP / 2, ty: y + GAP / 2, sx: cx + Math.cos(a) * R0, sy: cy + Math.sin(a) * R0, bend: (hash(i * 3 + 3) - .5) * .9, delay: 1.2 + 1.05 * hash(i * 7 + 5) });\n        }\n      }\n      return { W, H, s, cx, cy, grid, fly, diag };\n    };\n    const frame = (ctx, t) => {\n      const { W, H, s, grid, fly, diag, cx, cy } = L;\n      ctx.clearRect(0, 0, W, H);\n      const base = new Path2D(), hot = new Path2D(), add = (p, x, y, r) => { p.moveTo(x + r, y); p.arc(x, y, r, 0, Math.PI * 2); };\n      for (const g of grid) {\n        const appear = clamp((t - g.d / diag * 1.2) / .3); if (appear <= 0) continue;\n        let bump = 0;\n        for (const p of PULSES) { const age = t - p; if (age > 0 && age < 1.6) bump += Math.exp(-(((g.d - age * 900 * s) / (46 * s)) ** 2)) * (1 - age / 1.6); }\n        const ang = Math.atan2(g.y - cy, g.x - cx), push = bump * 7 * s;\n        const lit = g.letter ? clamp((t - 2.5 - g.h * .6) / .4) : 0;\n        add(lit > .5 || bump > .45 ? hot : base, g.x + Math.cos(ang) * push, g.y + Math.sin(ang) * push, (1.05 + bump * 1.6 + lit * 1.2) * Math.max(.6, s) * (.4 + .6 * appear));\n      }\n      for (const f of fly) {\n        const p = clamp((t - f.delay) / 1.15); if (p <= 0) continue;\n        const e = ease(p), mx = (f.sx + f.tx) / 2 - (f.ty - f.sy) * f.bend, my = (f.sy + f.ty) / 2 + (f.tx - f.sx) * f.bend;\n        add(hot, (1 - e) ** 2 * f.sx + 2 * (1 - e) * e * mx + e * e * f.tx, (1 - e) ** 2 * f.sy + 2 * (1 - e) * e * my + e * e * f.ty, (1.2 + 1.1 * e) * Math.max(.6, s));\n      }\n      ctx.fillStyle = C.dim; ctx.globalAlpha = C.night ? .4 : .45; ctx.fill(base);\n      ctx.fillStyle = C.accent; ctx.globalAlpha = 1; ctx.fill(hot);\n      CAPS.forEach((cap, k) => { // 字幕：文字下方居中，带编号\n        const a = t - CAP_AT(k), life = .62; if (a < 0 || a > life) return;\n        const o = clamp(a / .12) * clamp((life - a) / .14), dy = (1 - clamp(a / .2)) * 18 * s, fs = Math.max(14, Math.min(W * .05, 56 * s));\n        ctx.globalAlpha = o; ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';\n        ctx.fillStyle = C.ink; ctx.font = `900 ${fs}px \"Songti SC\",\"STSong\",\"Noto Serif SC\",serif`; ctx.fillText(cap, W / 2, H * .86 + dy);\n        ctx.fillStyle = C.accent; ctx.font = `500 ${Math.max(9, fs * .24)}px \"SF Mono\",Menlo,monospace`;\n        ctx.fillText(`${String(k + 1).padStart(2, '0')} / ${String(CAPS.length).padStart(2, '0')}`, W / 2, H * .86 - fs * 1.05 + dy);\n      });\n      ctx.globalAlpha = 1;\n    };\n    return MH.canvasHost(el, opts, h => {\n      C = h.colors();\n      return {\n        ghostClick: false,\n        resize(W, H) { L = layout(W, H, h.s); },\n        theme() { C = h.colors(); },\n        down() { t0 = performance.now(); },\n        frame(now) {\n          if (!L) return;\n          if (MH.still()) return frame(h.ctx, T_END);\n          const t = ((now - t0) / 1000) % (T_END + HOLD); // 播完定格一会儿，再从头播\n          frame(h.ctx, Math.min(t, T_END));\n        },\n      };\n    });\n  },\n});\n","src/effects/pipeline.js":"// ───── 校验链：一个小点依次走过各道关，走过的关点亮，到终点停一下再重来 ─────\nMH.register({\n  id: 'pipeline', name: '校验链', cat: '交互', tech: 'SVG · 分段缓动',\n  desc: '一次操作依次经过多道检查：小点在每道关前减速、通过后点亮，适合解释流程或状态机。',\n  mount(el, opts) {\n    const G = opts.gates || ['计划', '身份', '权限', '状态', '幂等', '限流', '审计'];\n    el.insertAdjacentHTML('beforeend', `<div class=\"pl\"><svg></svg></div>`);\n    const box = el.lastElementChild, svg = box.querySelector('svg');\n    let gates, labels, pl, tk, x;\n    const build = () => {\n      const W = Math.max(box.clientWidth, 240), gap = (W - 60) / (G.length - 1), y = 40;\n      x = i => 30 + i * gap; svg.setAttribute('viewBox', `0 0 ${W} 90`);\n      svg.innerHTML = `<line class=\"ln\" x1=\"${x(0)}\" y1=\"${y}\" x2=\"${x(G.length - 1)}\" y2=\"${y}\"/><line class=\"lnon\" x1=\"${x(0)}\" y1=\"${y}\" x2=\"${x(0)}\" y2=\"${y}\"/>` +\n        G.map((g, i) => `<rect class=\"g\" x=\"${x(i) - 8}\" y=\"${y - 8}\" width=\"16\" height=\"16\" ${i === 0 || i === G.length - 1 ? 'rx=\"8\"' : ''}/><text x=\"${x(i)}\" y=\"${y + 36}\">${g}</text>`).join('') +\n        `<circle class=\"tok\" cx=\"${x(0)}\" cy=\"${y}\" r=\"5\"/>`;\n      gates = [...svg.querySelectorAll('.g')]; labels = [...svg.querySelectorAll('text')]; pl = svg.querySelector('.lnon'); tk = svg.querySelector('.tok');\n    };\n    const ro = new ResizeObserver(build); ro.observe(box); build();\n    const set = p => { const px = x(0) + p * (x(1) - x(0)); pl.setAttribute('x2', px); tk.setAttribute('cx', px); gates.forEach((g, i) => { g.classList.toggle('on', p >= i - .02); labels[i].classList.toggle('on', p >= i - .02); }); };\n    let running = false, raf = 0;\n    const N = G.length - 1, T = 7000;\n    const loop = now => {\n      if (!running) return;\n      const raw = Math.min((now % T) / T * 1.25, 1) * N, i = Math.floor(raw), f = raw - i;\n      set(Math.min(i + (f < .5 ? 2 * f * f : 1 - (-2 * f + 2) ** 2 / 2), N));\n      raf = requestAnimationFrame(loop);\n    };\n    return {\n      pause() { running = false; cancelAnimationFrame(raf); },\n      resume() { if (running) return; if (MH.still()) return set(N); running = true; raf = requestAnimationFrame(loop); },\n      destroy() { this.pause(); ro.disconnect(); box.remove(); },\n    };\n  },\n});\n","src/effects/pull.js":"// 拉扯翻页：一页一屏，换页时只有页面上的信息被扯长、扯走，背景不动。\n// 做法：把要被扯走的那一页复制一份，横切成很多细条；每条按离“抓点”的远近做竖向位移和拉伸，拼起来就是被拉长的样子。\n// 只做竖向（横向不缩放），字的边缘才是连续的，没有台阶。\nMH.register({\n  id: 'pull', name: '拉扯翻页', cat: '翻页', tech: 'DOM 切条 · 指数衰减位移 · 指针拖动',\n  desc: '往下翻，当前页的信息先被扯长，再整体拽走；往上翻，上一页从底部被拉上来。也可以按住拖动，拖过两成或甩得够快就翻页，否则弹回。',\n  usage: `const deck = MH.effects.find(e => e.id === 'pull').mount(el, { slides: ['…', '…'] });\\ndeck.resume();`,\n  mount(el, opts) {\n    const PAGES = opts.slides || [['01', '背景', '等高线 · 点阵 · 风场 · 网格'], ['02', '过渡', '11 种深浅切换'], ['03', '翻页', '拉扯翻页'], ['04', '交互', '片头 · 开关 · 卡片 · 光标']];\n    el.insertAdjacentHTML('beforeend', `<div class=\"pd\">${PAGES.map(([n, t, d]) => `<section class=\"pd-slide\"><div class=\"pd-n\">${n}</div><div><h3>${t}</h3><p>${d}</p></div></section>`).join('')}<div class=\"pd-pn\"></div></div>`);\n    const box = el.lastElementChild, slides = [...box.querySelectorAll('.pd-slide')], pn = box.querySelector('.pd-pn');\n    const { clamp, lerp, ease, tween } = MH;\n    let cur = 0, busy = false, dirStep = 1, running = false, timer = 0, lastReal = -1e9;\n    slides[0].classList.add('on');\n    const paint = () => { pn.textContent = `${String(cur + 1).padStart(2, '0')} / ${String(slides.length).padStart(2, '0')}`; };\n    paint();\n\n    // 快照切条：整数像素对齐，静止时不重叠也没有缝\n    function sheetOf(node) {\n      const W = box.clientWidth, H = box.clientHeight, N = Math.max(16, Math.round(H / 24));\n      const sheet = document.createElement('div'); sheet.className = 'pd-sheet';\n      const strips = [];\n      for (let i = 0; i < N; i++) {\n        const y0 = Math.floor(i * H / N), y1 = Math.floor((i + 1) * H / N);\n        const s = document.createElement('div'); s.className = 'pd-band'; s.style.top = y0 + 'px'; s.style.height = y1 - y0 + 'px';\n        const c = node.cloneNode(true); c.classList.add('on'); c.style.cssText = `top:${-y0}px;height:${H}px;opacity:1;transform:none`;\n        s.append(c); sheet.append(s); strips.push({ el: s, y0, y1 });\n      }\n      box.append(sheet);\n      return { sheet, strips, H };\n    }\n    // dir=down：抓点 gy 上方按距离指数衰减地跟随（被拉长），下方整体跟走；dir=up：上沿领先、下面落后。g 是整体跟上的比例\n    function place(S, { dir, p, g, L, gy }) {\n      const H = S.H;\n      const D = dir === 'down' ? y => p * (g + (1 - g) * (y >= gy ? 1 : Math.exp(-(gy - y) / L))) : y => H - p * (g + (1 - g) * Math.exp(-y / L));\n      for (const s of S.strips) { const a = D(s.y0), b = D(s.y1), h = s.y1 - s.y0; s.el.style.transform = `translate3d(0,${a}px,0) scaleY(${Math.max(.2, (h + b - a) / h)})`; }\n    }\n    const enter = (e, k, from) => { e.style.opacity = k; e.style.transform = `translateY(${(1 - k) * from}px)`; };\n    const reset = e => { e.style.opacity = ''; e.style.transform = ''; };\n\n    async function go(to) {\n      if (busy || to === cur) return;\n      const H = box.clientHeight, off = 28 * MH.scaleOf(box.clientWidth);\n      if (to < 0 || to >= slides.length) { // 到头：拽动一点又弹回\n        busy = true; const e = slides[cur], d = to > cur ? 1 : -1;\n        await tween(160, k => e.style.transform = `translateY(${d * 34 * ease.out(k)}px) scaleY(${1 + .03 * ease.out(k)})`);\n        await tween(380, k => e.style.transform = `translateY(${d * 34 * (1 - ease.back(k))}px)`);\n        reset(e); busy = false; return;\n      }\n      busy = true;\n      const from = slides[cur], next = slides[to];\n      if (to > cur) { // 下一页：当前页的信息先被往下扯长，再整体拽走、淡出；下一页稍后从上方浮现\n        const S = sheetOf(from), L = H * .35;\n        from.classList.remove('on'); next.classList.add('on'); enter(next, 0, -off); cur = to; paint();\n        await tween(320, k => place(S, { dir: 'down', p: H * .14 * ease.out(k), g: 0, L, gy: H }));\n        await tween(440, k => { place(S, { dir: 'down', p: lerp(H * .14, H * 1.1, ease.in(k)), g: ease.inOut(k), L, gy: H }); S.sheet.style.opacity = 1 - clamp((k - .1) / .6); enter(next, ease.out(clamp((k - .45) / .55)), -off); });\n        reset(next); S.sheet.remove();\n      } else { // 上一页：从底部探出头，被扯着上沿拉到顶，轻轻回弹；当前页往上淡出\n        const S = sheetOf(next), L = H * .4;\n        place(S, { dir: 'up', p: 0, g: 0, L, gy: 0 }); S.sheet.style.opacity = 0;\n        await tween(180, k => { place(S, { dir: 'up', p: 46 * ease.out(k), g: 0, L, gy: 0 }); S.sheet.style.opacity = k; });\n        await tween(300, k => { place(S, { dir: 'up', p: lerp(46, H * .32, ease.out(k)), g: 0, L, gy: 0 }); from.style.opacity = 1 - .6 * k; from.style.transform = `translateY(${-24 * k}px)`; });\n        await tween(460, k => { place(S, { dir: 'up', p: lerp(H * .32, H, ease.back(k)), g: ease.out(k), L, gy: 0 }); from.style.opacity = .4 * (1 - ease.out(k)); });\n        from.classList.remove('on'); reset(from); next.classList.add('on'); cur = to; paint(); S.sheet.remove();\n      }\n      busy = false;\n    }\n\n    // 输入：舞台上滚轮、方向键；按住拖动（指针按住的地方就是抓点）\n    let acc = 0, coolUntil = 0, drag = null;\n    const onWheel = e => {\n      e.preventDefault(); lastReal = performance.now();\n      if (busy || performance.now() < coolUntil) return;\n      acc += e.deltaY;\n      if (Math.abs(acc) > 40) { const d = acc > 0 ? 1 : -1; acc = 0; coolUntil = performance.now() + 900; go(cur + d); }\n    };\n    const onKey = e => {\n      if (!box.isConnected || !running) return;\n      if (['ArrowDown', 'PageDown'].includes(e.key)) { e.preventDefault(); lastReal = performance.now(); go(cur + 1); }\n      if (['ArrowUp', 'PageUp'].includes(e.key)) { e.preventDefault(); lastReal = performance.now(); go(cur - 1); }\n    };\n    const pose = (dir, dy, H) => dir === 'down'\n      ? (p => ({ p, g: clamp(p / (H * .9)) ** 2, q: clamp(p / (H * .5)) }))(Math.max(0, dy))\n      : (p => ({ p, g: clamp(p / (H * .9)) ** 2, q: clamp(p / (H * .6)) }))(clamp(-dy * 1.15, 0, H));\n    const onDown = e => {\n      if (busy || e.button > 0 || e.target.closest('a, button')) return;\n      const r = box.getBoundingClientRect(); lastReal = performance.now();\n      drag = { y: e.clientY, gy: e.clientY - r.top, v: 0, ly: e.clientY, lt: performance.now(), S: null, dir: null };\n      box.setPointerCapture(e.pointerId);\n    };\n    const onMove = e => {\n      if (!drag) return;\n      const dy = e.clientY - drag.y, now = performance.now(), H = box.clientHeight, off = 28 * MH.scaleOf(box.clientWidth);\n      drag.v = (e.clientY - drag.ly) / Math.max(1, now - drag.lt); drag.ly = e.clientY; drag.lt = now; lastReal = now;\n      if (!drag.dir) {\n        if (Math.abs(dy) < 8) return;\n        drag.dir = dy > 0 ? 'down' : 'up';\n        const to = cur + (drag.dir === 'down' ? 1 : -1);\n        if (to < 0 || to >= slides.length) { drag.edge = true; return; }\n        busy = true; drag.to = to;\n        if (drag.dir === 'down') { drag.S = sheetOf(slides[cur]); slides[cur].classList.remove('on'); slides[to].classList.add('on'); enter(slides[to], 0, -off); }\n        else drag.S = sheetOf(slides[to]);\n      }\n      if (drag.edge) { const d = dy * .18; slides[cur].style.transform = `translateY(${d}px) scaleY(${1 + Math.abs(d) / H * .6})`; return; }\n      const { p, g, q } = pose(drag.dir, dy, H);\n      if (drag.dir === 'down') { place(drag.S, { dir: 'down', p, g, L: H * .3, gy: drag.gy }); drag.S.sheet.style.opacity = 1 - .7 * q; enter(slides[drag.to], .8 * q, -off); }\n      else { place(drag.S, { dir: 'up', p, g, L: H * .4, gy: 0 }); drag.S.sheet.style.opacity = clamp(p / (H * .15)); slides[cur].style.opacity = 1 - .8 * q; slides[cur].style.transform = `translateY(${-30 * q}px)`; }\n    };\n    const onUp = async e => {\n      const d = drag; drag = null;\n      if (!d || !d.dir) return;\n      const H = box.clientHeight, off = 28 * MH.scaleOf(box.clientWidth);\n      if (d.edge) { const e2 = slides[cur], m = /translateY\\(([-\\d.]+)px\\)/.exec(e2.style.transform), y0 = m ? +m[1] : 0; await tween(320, k => e2.style.transform = `translateY(${y0 * (1 - ease.back(k))}px)`); reset(e2); return; }\n      const dy = e.clientY - d.y, { p: p0, g: g0, q: q0 } = pose(d.dir, dy, H);\n      const done = d.dir === 'down' ? (dy > H * .22 || d.v > .9) : (-dy > H * .22 || d.v < -.9);\n      const from = slides[cur], next = slides[d.to];\n      if (d.dir === 'down') {\n        if (done) { await tween(360, k => { place(d.S, { dir: 'down', p: lerp(p0, H * 1.1, ease.in(k)), g: lerp(g0, 1, ease.out(k)), L: H * .3, gy: d.gy }); d.S.sheet.style.opacity = (1 - .7 * q0) * (1 - k); enter(next, lerp(.8 * q0, 1, ease.out(k)), -off); }); reset(next); cur = d.to; paint(); }\n        else { await tween(420, k => { place(d.S, { dir: 'down', p: p0 * (1 - ease.back(k)), g: g0 * (1 - k), L: H * .3, gy: d.gy }); d.S.sheet.style.opacity = lerp(1 - .7 * q0, 1, k); enter(next, .8 * q0 * (1 - k), -off); }); next.classList.remove('on'); reset(next); from.classList.add('on'); }\n      } else {\n        if (done) { await tween(420, k => { place(d.S, { dir: 'up', p: lerp(p0, H, ease.back(k)), g: lerp(g0, 1, ease.out(k)), L: H * .4, gy: 0 }); d.S.sheet.style.opacity = 1; from.style.opacity = (1 - .8 * q0) * (1 - k); }); from.classList.remove('on'); reset(from); next.classList.add('on'); cur = d.to; paint(); }\n        else { await tween(360, k => { place(d.S, { dir: 'up', p: p0 * (1 - ease.out(k)), g: g0 * (1 - k), L: H * .4, gy: 0 }); enter(from, lerp(1 - .8 * q0, 1, k), 0); from.style.transform = `translateY(${-30 * q0 * (1 - k)}px)`; }); reset(from); }\n      }\n      d.S.sheet.remove(); busy = false;\n    };\n    box.addEventListener('wheel', onWheel, { passive: false });\n    box.addEventListener('pointerdown', onDown); box.addEventListener('pointermove', onMove); box.addEventListener('pointerup', onUp); box.addEventListener('pointercancel', onUp);\n    addEventListener('keydown', onKey);\n    // 没人操作时自动来回翻：到最后一页就往回翻\n    const auto = () => {\n      if (!running) return;\n      if (performance.now() - lastReal > 3500 && !busy) {\n        if (cur + dirStep < 0 || cur + dirStep >= slides.length) dirStep = -dirStep;\n        go(cur + dirStep);\n      }\n      timer = setTimeout(auto, 2400);\n    };\n    return {\n      pause() { running = false; clearTimeout(timer); },\n      resume() { if (running) return; running = true; if (!MH.still()) timer = setTimeout(auto, 1600); },\n      destroy() { this.pause(); removeEventListener('keydown', onKey); box.remove(); },\n    };\n  },\n});\n","src/effects/scramble.js":"// 小交互：DOM + CSS，没有画布。用 canvasHost 的无画布模式拿到“真实指针或幽灵光标”的位置。\n\n// ───── 乱码落定：文字先变成一串随机符号，再从左到右一个个落定 ─────\nMH.register({\n  id: 'scramble', name: '乱码落定', cat: '交互', tech: 'requestAnimationFrame · 文本替换',\n  desc: '指针经过时，文字先变成乱码，再从左到右一个个落回原字，适合导航和标题。',\n  mount(el, opts) {\n    const WORDS = ['MOTION HUB', '背景 · 过渡 · 翻页', 'HELLO, LJY'];\n    el.insertAdjacentHTML('beforeend', `<div class=\"sc\">${WORDS.map(w => `<div class=\"sc-w\" data-s=\"${w}\">${w}</div>`).join('')}</div>`);\n    const box = el.lastElementChild, items = [...box.children], pool = '01#/<>+=*[]{}%$&';\n    const play = a => {\n      if (a._busy || MH.still()) return; a._busy = true;\n      const s = a.dataset.s, t0 = performance.now();\n      const tick = now => {\n        const k = Math.floor((now - t0) / 55);\n        a.textContent = [...s].map((ch, i) => i < k || ch === ' ' ? ch : pool[Math.random() * pool.length | 0]).join('');\n        if (k <= s.length) requestAnimationFrame(tick); else { a.textContent = s; a._busy = false; }\n      };\n      requestAnimationFrame(tick);\n    };\n    let last = null;\n    return MH.canvasHost(el, opts, h => ({\n      frame() {\n        const r0 = el.getBoundingClientRect();\n        const over = items.find(a => { const r = a.getBoundingClientRect(), x = h.P.x + r0.left, y = h.P.y + r0.top; return x >= r.left && x <= r.right && y >= r.top && y <= r.bottom; });\n        if (over && over !== last) play(over);\n        items.forEach(a => a.classList.toggle('hot', a === over));\n        last = over || null;\n      },\n    }), { canvas: false });\n  },\n});\n","src/effects/sun-moon.js":"// ───── 太阳 ⇄ 月亮：一个圆 + 一个“咬掉一口”的遮罩 + 八条光芒；遮罩移进来、光芒收起就是月亮 ─────\nMH.register({\n  id: 'sun-moon', name: '太阳月亮开关', cat: '交互', tech: 'SVG 遮罩 · CSS 变换',\n  desc: '深浅模式开关的图标：浅色时是月亮（点了变深色），深色时是太阳；切换时光芒收起、圆被咬掉一口变成月牙。',\n  mount(el, opts) {\n    const rays = [0, 45, 90, 135, 180, 225, 270, 315].map(a => `<line x1=\"12\" y1=\"2.5\" x2=\"12\" y2=\"4.5\" transform=\"rotate(${a} 12 12)\"/>`).join('');\n    const id = 'sm' + Math.random().toString(36).slice(2, 7);\n    el.insertAdjacentHTML('beforeend', `<div class=\"ui-center\"><button class=\"sm moon\" type=\"button\" aria-label=\"切换\"><svg viewBox=\"0 0 24 24\"><mask id=\"${id}\"><rect x=\"-4\" y=\"-4\" width=\"32\" height=\"32\" fill=\"#fff\"/><circle class=\"bite\" cx=\"28\" cy=\"2\" r=\"7.5\" fill=\"#000\"/></mask><circle class=\"core\" cx=\"12\" cy=\"12\" r=\"5\" fill=\"currentColor\" mask=\"url(#${id})\"/><g class=\"rays\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\">${rays}</g></svg></button><span class=\"sm-tip\">点一下</span></div>`);\n    const box = el.lastElementChild, btn = box.querySelector('.sm');\n    let running = false, timer = 0, lastReal = -1e9;\n    btn.addEventListener('click', () => { lastReal = performance.now(); btn.classList.toggle('moon'); });\n    const auto = () => { if (!running) return; if (performance.now() - lastReal > 3000) btn.classList.toggle('moon'); timer = setTimeout(auto, 1800); };\n    return { pause() { running = false; clearTimeout(timer); }, resume() { if (running || MH.still()) return; running = true; timer = setTimeout(auto, 1200); }, destroy() { this.pause(); box.remove(); } };\n  },\n});\n","src/effects/transitions.js":"// 深浅切换过渡。两种用法：\n//   1. 缩略图 / 全屏体验：容器里叠两层“小页面”（浅色、深色），新的一层按选定形状盖上去。不依赖 View Transitions。\n//   2. 真实网站：MH.themeSwitch(event, apply, fx) 用 View Transitions 给整页做同样的过渡（见本文件末尾）。\n// 形状函数 shape(x, y, R, W, H, s) 返回 WAAPI 关键帧；x/y 是触发点，R 是触发点到最远角的距离，s 是缩放系数。\n(() => {\n  const FX = {\n    circle: { name: '圆形揭开', dur: 650, desc: '从点击处放大一个圆，盖住整页。',\n      shape: (x, y, R) => [{ clipPath: `circle(0px at ${x}px ${y}px)` }, { clipPath: `circle(${R}px at ${x}px ${y}px)` }] },\n    ink: { name: '墨水晕开', dur: 900, desc: '从点击处开始，边缘是圆润的不规则形，先快后慢，像墨滴洇开。',\n      shape: (x, y, R) => {\n        const N = 96, ph = [0, 0, 0].map(() => Math.random() * 6.28);\n        const wob = Array.from({ length: N }, (_, i) => { const a = i / N * Math.PI * 2; return .88 + .07 * Math.sin(3 * a + ph[0]) + .05 * Math.sin(5 * a + ph[1]) + .03 * Math.sin(8 * a + ph[2]); });\n        const ring = k => `polygon(${wob.map((w, i) => { const a = i / N * Math.PI * 2, r = R * k * (k < 1 ? w : 1.3); return `${(x + Math.cos(a) * r).toFixed(1)}px ${(y + Math.sin(a) * r).toFixed(1)}px`; }).join(',')})`;\n        return [{ clipPath: ring(0) }, { clipPath: ring(.45), offset: .4 }, { clipPath: ring(1.25) }];\n      } },\n    dots: { name: '点阵扩散', dur: 1000, desc: '前沿是一圈网点，后面才是实心，适合配点阵背景。',\n      shape: (x, y, R, W, H, s) => [{ '--vr': '0px' }, { '--vr': `${R + 180 * s}px` }] },\n    blinds: { name: '百叶窗', dur: 700, desc: '一条条竖帘同时翻开，利落、有节奏。',\n      shape: (x, y, R, W, H, s) => [{ '--vw': '0px' }, { '--vw': `${72 * s}px` }] },\n    slice: { name: '斜切扫过', dur: 750, desc: '一道斜边从点击的那一侧扫向另一侧。',\n      shape: (x, y, R, W) => {\n        const L = x < W / 2, P = k => L ? `polygon(0 0, ${k}% 0, ${k - 35}% 100%, 0 100%)` : `polygon(100% 0, ${100 - k}% 0, ${135 - k}% 100%, 100% 100%)`;\n        return [{ clipPath: P(0) }, { clipPath: P(140) }];\n      } },\n    iris: { name: '光圈快门', dur: 800, desc: '六边形从点击处旋转着张开，像相机光圈。',\n      shape: (x, y, R) => Array.from({ length: 25 }, (_, f) => {\n        const k = f / 24, r = R * 1.25 * (k * k * (3 - 2 * k)), rot = k * 2.2;\n        return { clipPath: `polygon(${Array.from({ length: 6 }, (_, i) => { const a = rot + i * Math.PI / 3; return `${(x + Math.cos(a) * r).toFixed(1)}px ${(y + Math.sin(a) * r).toFixed(1)}px`; }).join(',')})` };\n      }) },\n    wave: { name: '液面上涨', dur: 1100, desc: '新颜色像水一样从底部涨上来，水面起伏。',\n      shape: (x, y, R, W, H, s) => Array.from({ length: 31 }, (_, f) => {\n        const k = f / 30, level = H * (1.08 - k * 1.25), amp = 46 * s * Math.sin(Math.PI * k), N = 32;\n        const top = Array.from({ length: N + 1 }, (_, i) => `${(W * i / N).toFixed(1)}px ${(level + amp * Math.sin(i / N * Math.PI * 3 + k * 9)).toFixed(1)}px`);\n        return { clipPath: `polygon(0 ${H}px, ${top.join(',')}, ${W}px ${H}px)` };\n      }) },\n    halftone: { name: '网点溶解', dur: 750, desc: '整屏同时长出印刷网点，越长越大，直到连成一片。',\n      shape: (x, y, R, W, H, s) => [{ '--vr': '0px' }, { '--vr': `${14 * s}px` }] },\n    soft: { name: '柔光圆', dur: 800, desc: '和圆形揭开一样从点击处扩散，但边缘是一圈柔和的渐隐。',\n      shape: (x, y, R, W, H, s) => [{ '--vr': '0px' }, { '--vr': `${R + 260 * s}px` }] },\n    flip: { name: '翻页', dur: 900, desc: '整页像卡片一样绕竖轴翻过去，背面就是另一种颜色。', shape: null },\n    fade: { name: '淡入淡出', dur: 400, desc: '最普通的渐变，作对照。', shape: () => [{ opacity: 0 }, { opacity: 1 }] },\n  };\n  const EASE = 'cubic-bezier(.6,0,.2,1)';\n  // 遮罩里用到的尺寸（随缩放系数变）：点阵前沿宽度、网点格子、柔光边宽、百叶窗周期\n  const sizeVars = (el, s) => {\n    el.style.setProperty('--band', `${160 * s}px`); el.style.setProperty('--tile', `${18 * s}px`);\n    el.style.setProperty('--soft', `${260 * s}px`); el.style.setProperty('--period', `${72 * s}px`);\n  };\n\n  // 小页面：同一份内容，浅色一层、深色一层\n  const scene = theme => `<div class=\"tt-scene\" data-theme=\"${theme}\"><div class=\"tt-mock\">\n    <span class=\"tt-tag\">${theme === 'night' ? '深色' : '浅色'}</span><b>Aa</b><i></i><i></i><i class=\"short\"></i></div></div>`;\n\n  function mountTransition(id) {\n    const fx = FX[id];\n    return (el, opts) => {\n      el.insertAdjacentHTML('beforeend', `<div class=\"tt\">${scene('day')}${scene('night')}</div>`);\n      const box = el.lastElementChild, [day, night] = box.children;\n      let cur = 'day', running = false, timer = 0, lastReal = -1e9, settle = null;\n      night.style.visibility = 'hidden';\n      // 过渡播完之前再点不生效，等这一次播完才能再切（连点时被打断很生硬）\n      const play = (x, y) => {\n        if (settle) return;\n        const W = box.clientWidth, H = box.clientHeight, s = MH.scaleOf(W), R = Math.hypot(Math.max(x, W - x), Math.max(y, H - y));\n        const top = cur === 'day' ? night : day, bottom = cur === 'day' ? day : night;\n        cur = cur === 'day' ? 'night' : 'day'; // 目标状态立刻生效\n        sizeVars(top, s); top.style.setProperty('--vx', x + 'px'); top.style.setProperty('--vy', y + 'px');\n        top.dataset.fx = id; top.style.zIndex = 2; bottom.style.zIndex = 1; top.style.visibility = 'visible';\n        const anims = []; let done = false;\n        settle = () => {\n          if (done) return; done = true; settle = null;\n          anims.forEach(a => a.cancel());\n          delete top.dataset.fx; top.style.visibility = 'visible'; bottom.style.visibility = 'hidden';\n          top.style.zIndex = 1; bottom.style.zIndex = 0;\n        };\n        if (MH.still()) return settle();\n        const quiet = () => {}; // 被打断时动画会被 cancel，finished 会 reject，忽略即可\n        if (id === 'flip') {\n          const o = { duration: fx.dur / 2, easing: 'cubic-bezier(.5,0,.5,1)', fill: 'both' };\n          top.style.visibility = 'hidden';\n          const a1 = bottom.animate([{ transform: 'rotateY(0)' }, { transform: 'rotateY(90deg)' }], o); anims.push(a1);\n          a1.finished.then(() => {\n            if (done) return;\n            top.style.visibility = 'visible'; bottom.style.visibility = 'hidden';\n            const a2 = top.animate([{ transform: 'rotateY(-90deg)' }, { transform: 'rotateY(0)' }], o); anims.push(a2);\n            a2.finished.then(settle, quiet);\n          }, quiet);\n        } else {\n          const a = top.animate(fx.shape(x, y, R, W, H, s), { duration: fx.dur, easing: EASE }); anims.push(a);\n          a.finished.then(settle, quiet);\n        }\n      };\n      const onDown = e => { lastReal = performance.now(); const r = box.getBoundingClientRect(); play(e.clientX - r.left, e.clientY - r.top); };\n      box.addEventListener('pointerdown', onDown);\n      // 缩略图里没人点的时候，每隔一会儿在“幽灵光标”的位置自己触发一次\n      const auto = () => {\n        if (!running) return;\n        if (!opts.expanded && performance.now() - lastReal > 3000) { const g = MH.ghostAt(performance.now(), box.clientWidth, box.clientHeight, MH.hash(id.length)); play(g.x, g.y); }\n        timer = setTimeout(auto, 2600 + fx.dur);\n      };\n      return {\n        pause() { running = false; clearTimeout(timer); },\n        resume() { if (running || MH.still()) return; running = true; timer = setTimeout(auto, 900); },\n        destroy() { this.pause(); box.removeEventListener('pointerdown', onDown); box.remove(); },\n      };\n    };\n  }\n  for (const [id, fx] of Object.entries(FX)) {\n    MH.register({ id: `theme-${id}`, name: fx.name, cat: '过渡', tech: id === 'flip' ? 'WAAPI · 3D 变换' : (/dots|blinds|halftone|soft/.test(id) ? 'CSS 遮罩 · @property' : 'WAAPI · clip-path'), desc: fx.desc + ' 点画面任意位置触发。', mount: mountTransition(id) });\n  }\n\n  // ───── 真实网站用：整页深浅切换 ─────\n  // apply() 负责真正改主题（例如切换 <html data-theme>）；不支持 View Transitions 或减少动态效果时直接调用 apply()。\n  // 过渡播完之前再点不生效，等这一次播完才能再切。\n  let active = null;\n  MH.themeSwitch = (e, apply, id = 'dots') => {\n    const fx = FX[id] || FX.dots, root = document.documentElement;\n    if (!document.startViewTransition || MH.still()) return apply();\n    if (active) return;\n    const r = e.currentTarget && e.currentTarget.getBoundingClientRect ? e.currentTarget.getBoundingClientRect() : { left: innerWidth / 2, top: innerHeight / 2, width: 0, height: 0 };\n    const x = e.clientX || r.left + r.width / 2, y = e.clientY || r.top + r.height / 2;\n    const W = innerWidth, H = innerHeight, R = Math.hypot(Math.max(x, W - x), Math.max(y, H - y)), s = 1;\n    root.dataset.vfx = id; sizeVars(root, s);\n    root.style.setProperty('--vx', x + 'px'); root.style.setProperty('--vy', y + 'px');\n    const vt = document.startViewTransition(apply); active = vt;\n    vt.ready.then(() => {\n      if (id === 'flip') {\n        const o = { duration: fx.dur / 2, easing: 'cubic-bezier(.5,0,.5,1)', fill: 'both' };\n        root.animate([{ transform: 'perspective(1800px) rotateY(0)' }, { transform: 'perspective(1800px) rotateY(90deg)' }], { ...o, pseudoElement: '::view-transition-old(root)' });\n        root.animate([{ transform: 'perspective(1800px) rotateY(-90deg)' }, { transform: 'perspective(1800px) rotateY(0)' }], { ...o, delay: fx.dur / 2, pseudoElement: '::view-transition-new(root)' });\n      } else if (fx.shape && id !== 'fade') {\n        root.animate(fx.shape(x, y, R, W, H, s), { duration: fx.dur, easing: EASE, pseudoElement: '::view-transition-new(root)' });\n      }\n    }).catch(() => {});\n    vt.finished.finally(() => { if (active === vt) { active = null; delete root.dataset.vfx; } });\n  };\n  // 绑定深浅开关（过渡播完之前再点不生效）\n  MH.bindThemeToggle = (btn, apply, id = 'dots') => btn.addEventListener('click', e => MH.themeSwitch(e, apply, id));\n  MH.themeFx = Object.keys(FX);\n})();\n"};
